/* ============================================================
   RedRoom Fitness — Global Stylesheet
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

/* ── Reset & Base ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red:      #FF0000;
  --red-dark: #CC0000;
  --bg:       #141414;
  --bg2:      #1a1a1a;
  --bg3:      #222222;
  --white:    #FFFFFF;
  --gray:     #AAAAAA;
  --gray2:    #666666;
  --border:   #2e2e2e;
  --font-head: 'Oswald', 'Arial Narrow', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', sans-serif;
  --max-w:    1280px;
  --nav-h:    72px;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Typography ───────────────────────────────────────────── */
h1, h2, h3, h4, h5 {
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

.section-tag {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--red);
  display: block;
  margin-bottom: 12px;
}

/* ── Buttons ──────────────────────────────────────────────── */
.btn {
  display: inline-block;
  font-family: var(--font-head);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 36px;
  border-radius: 2px;
  transition: all 0.2s ease;
  cursor: pointer;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
  border: 2px solid var(--red);
}
.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--bg);
  transform: translateY(-1px);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border: 2px solid var(--red);
}
.btn-outline-red:hover {
  background: var(--red);
  color: var(--white);
}

/* ── Top Promo Bar ────────────────────────────────────────── */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 24px;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.05em;
  position: relative;
  z-index: 200;
}
.promo-bar a {
  color: var(--white);
  font-weight: 700;
  margin-left: 8px;
  text-decoration: underline;
}

/* ── Navigation ───────────────────────────────────────────── */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(20, 20, 20, 0.97);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
  height: var(--nav-h);
  display: flex;
  align-items: center;
}

.navbar .container {
  display: flex;
  align-items: center;
  width: 100%;
}

.nav-logo {
  font-family: var(--font-head);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--white);
  text-transform: uppercase;
  flex-shrink: 0;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0;
  margin: 0 auto;
  padding: 0 24px;
}
.nav-links a {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0 16px;
  color: var(--gray);
  transition: color 0.2s;
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--white); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.nav-actions .btn {
  padding: 10px 20px;
  font-size: 12px;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  margin-left: auto;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all 0.3s;
}

/* ── Hero ─────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 90vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--bg);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a0505 40%, #2a0808 100%);
  z-index: 0;
}

.hero-bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 70% 50%, rgba(255, 0, 0, 0.12) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(255, 0, 0, 0.06) 0%, transparent 60%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}

.hero h1 {
  font-size: clamp(52px, 8vw, 96px);
  font-weight: 700;
  line-height: 1;
  color: var(--white);
  margin-bottom: 24px;
}
.hero h1 em {
  color: var(--red);
  font-style: normal;
}

.hero-sub {
  font-size: 18px;
  color: var(--gray);
  max-width: 560px;
  margin-bottom: 40px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-page-title {
  font-size: clamp(42px, 6vw, 80px);
}

/* ── Sections ─────────────────────────────────────────────── */
.section {
  padding: 100px 0;
}
.section-sm {
  padding: 64px 0;
}
.section-dark {
  background: var(--bg);
}
.section-darker {
  background: #0d0d0d;
}
.section-alt {
  background: var(--bg2);
}

.section-header {
  margin-bottom: 60px;
}
.section-header.centered {
  text-align: center;
}

.section-header h2 {
  font-size: clamp(36px, 5vw, 64px);
  font-weight: 700;
}

.section-header p {
  font-size: 17px;
  color: var(--gray);
  max-width: 640px;
  margin-top: 16px;
  line-height: 1.7;
}

.section-header.centered p {
  margin: 16px auto 0;
}

/* ── Community Promo ──────────────────────────────────────── */
.community-promo {
  background: var(--bg2);
  text-align: center;
  padding: 80px 0;
}
.community-promo h2 {
  font-size: clamp(40px, 6vw, 72px);
  color: var(--red);
  margin-bottom: 24px;
}
.community-promo p {
  font-size: 18px;
  color: var(--gray);
  max-width: 680px;
  margin: 0 auto 36px;
  line-height: 1.7;
}

/* ── Two Ways ─────────────────────────────────────────────── */
.two-ways {
  background: var(--bg);
}
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 60px;
}
.way-card {
  background: var(--bg2);
  padding: 64px 48px;
  position: relative;
  overflow: hidden;
  transition: background 0.3s;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s;
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { background: #1f1f1f; }

.way-number {
  font-family: var(--font-head);
  font-size: 80px;
  font-weight: 700;
  color: var(--border);
  line-height: 1;
  margin-bottom: 24px;
}
.way-card h3 {
  font-size: 32px;
  color: var(--white);
  margin-bottom: 16px;
}
.way-card p {
  color: var(--gray);
  font-size: 16px;
  line-height: 1.7;
}

/* ── Studio Experience ────────────────────────────────────── */
.studio-exp {
  background: linear-gradient(135deg, #0f0f0f 0%, #1a0505 50%, #0f0f0f 100%);
  text-align: center;
  padding: 120px 0;
}
.studio-exp h2 {
  font-size: clamp(40px, 6vw, 72px);
  max-width: 800px;
  margin: 0 auto 24px;
}
.studio-exp p {
  font-size: 18px;
  color: var(--gray);
  max-width: 640px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

/* ── Free Trial CTA ───────────────────────────────────────── */
.free-trial {
  background: var(--red);
  padding: 80px 0;
  text-align: center;
}
.free-trial h2 {
  font-size: clamp(36px, 5vw, 64px);
  margin-bottom: 32px;
  color: var(--white);
}
.free-trial .btn-outline {
  border-color: var(--white);
  color: var(--white);
  font-size: 18px;
  padding: 18px 48px;
}
.free-trial .btn-outline:hover {
  background: var(--white);
  color: var(--red);
}

/* ── Lifestyle Carousel ───────────────────────────────────── */
.carousel-section {
  background: var(--bg);
  padding: 80px 0;
}
.carousel-wrapper {
  position: relative;
  overflow: hidden;
  border-radius: 4px;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  height: 520px;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
}
.carousel-placeholder .icon {
  font-size: 48px;
  opacity: 0.3;
}
.carousel-placeholder span {
  font-family: var(--font-head);
  font-size: 20px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.5;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 56px;
  height: 56px;
  background: rgba(20,20,20,0.85);
  border: 1px solid var(--border);
  color: var(--white);
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 2px;
  z-index: 10;
  transition: background 0.2s, border-color 0.2s;
  cursor: pointer;
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-btn.prev { left: 16px; }
.carousel-btn.next { right: 16px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray2);
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
  border: none;
}
.carousel-dot.active {
  background: var(--red);
  transform: scale(1.3);
}

/* ── Newsletter ───────────────────────────────────────────── */
.newsletter {
  background: var(--bg2);
  padding: 80px 0;
}
.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h2 {
  font-size: clamp(28px, 4vw, 48px);
  margin-bottom: 12px;
}
.newsletter p {
  color: var(--gray);
  font-size: 16px;
  margin-bottom: 32px;
  line-height: 1.6;
}
.newsletter-form {
  display: flex;
  gap: 8px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter-form input {
  flex: 1;
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 15px;
  padding: 14px 18px;
  border-radius: 2px;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input.error { border-color: #ff4444; }
.newsletter-form input::placeholder { color: var(--gray2); }
.newsletter-form .btn {
  padding: 14px 28px;
  white-space: nowrap;
}

.form-msg {
  margin-top: 12px;
  font-size: 14px;
  min-height: 20px;
}
.form-msg.success { color: #44bb44; }
.form-msg.error   { color: #ff4444; }

/* ── Footer ───────────────────────────────────────────────── */
.footer {
  background: #0d0d0d;
  padding: 72px 0 40px;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 60px;
}
.footer-brand .nav-logo {
  font-size: 28px;
  display: block;
  margin-bottom: 16px;
}
.footer-brand p {
  color: var(--gray2);
  font-size: 14px;
  line-height: 1.7;
  max-width: 260px;
}
.footer-col h4 {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gray);
  margin-bottom: 20px;
}
.footer-col ul li {
  margin-bottom: 10px;
}
.footer-col ul li a {
  color: var(--gray2);
  font-size: 14px;
  transition: color 0.2s;
}
.footer-col ul li a:hover { color: var(--white); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p {
  color: var(--gray2);
  font-size: 13px;
}

/* Country Selector */
.country-selector {
  position: relative;
  display: inline-block;
}
.country-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--gray);
  font-family: var(--font-body);
  font-size: 13px;
  padding: 8px 14px;
  border-radius: 2px;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s;
}
.country-btn:hover {
  border-color: var(--gray2);
  color: var(--white);
}
.country-dropdown {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 2px;
  min-width: 180px;
  display: none;
  z-index: 50;
  box-shadow: 0 -8px 24px rgba(0,0,0,0.5);
}
.country-dropdown.open { display: block; }
.country-dropdown a {
  display: block;
  padding: 10px 16px;
  font-size: 14px;
  color: var(--gray);
  transition: background 0.15s, color 0.15s;
}
.country-dropdown a:hover {
  background: var(--bg2);
  color: var(--white);
}

/* ── The Workout Page ─────────────────────────────────────── */
.method-section {
  background: var(--bg);
  padding: 100px 0;
}
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.method-text h2 {
  font-size: clamp(36px, 5vw, 60px);
  margin-bottom: 24px;
}
.method-text p {
  font-size: 17px;
  color: var(--gray);
  line-height: 1.8;
}

.schedule-section {
  background: var(--bg2);
  padding: 100px 0;
}
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 48px;
}
.schedule-table th {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gray);
  padding: 16px 24px;
  border-bottom: 2px solid var(--border);
  text-align: left;
}
.schedule-table td {
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  font-size: 16px;
}
.schedule-table tr:last-child td { border-bottom: none; }
.schedule-table td:first-child {
  font-family: var(--font-head);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.schedule-table td .muscle-badge {
  display: inline-block;
  background: rgba(255,0,0,0.12);
  color: var(--red);
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 2px;
  border: 1px solid rgba(255,0,0,0.25);
}
.schedule-table tr:hover td { background: rgba(255,255,255,0.02); }

/* Floor/Treadmill Toggle */
.toggle-section {
  background: var(--bg);
  padding: 100px 0;
}
.toggle-header {
  text-align: center;
  margin-bottom: 48px;
}
.toggle-header h2 {
  font-size: clamp(32px, 4vw, 54px);
  margin-bottom: 32px;
}
.toggle-controls {
  display: inline-flex;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.toggle-btn {
  font-family: var(--font-head);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 48px;
  color: var(--gray);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 48px;
}
.toggle-panel {
  display: none;
  background: var(--bg2);
  padding: 64px 48px;
}
.toggle-panel.active { display: block; }
.toggle-panel h3 {
  font-size: 36px;
  color: var(--red);
  margin-bottom: 20px;
}
.toggle-panel p {
  font-size: 17px;
  color: var(--gray);
  line-height: 1.8;
}
.toggle-panel-full {
  grid-column: 1 / -1;
}

/* ── Instructors Page ─────────────────────────────────────── */
.filter-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-bar label {
  font-family: var(--font-head);
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gray);
  margin-right: 8px;
}
.filter-btn {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 10px 22px;
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--gray);
  border-radius: 2px;
  cursor: pointer;
  transition: all 0.2s;
}
.filter-btn:hover,
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
  transition: transform 0.2s, border-color 0.2s;
}
.instructor-card:hover {
  transform: translateY(-4px);
  border-color: var(--red);
}
.instructor-avatar {
  width: 100%;
  aspect-ratio: 1;
  background: var(--bg3);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-head);
  font-size: 48px;
  font-weight: 700;
  color: var(--red);
  position: relative;
  overflow: hidden;
}
.instructor-avatar::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,0,0,0.05) 0%, transparent 60%);
}
.instructor-info {
  padding: 24px;
}
.instructor-info h3 {
  font-size: 20px;
  margin-bottom: 8px;
}
.instructor-location {
  font-size: 13px;
  color: var(--gray2);
  letter-spacing: 0.08em;
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 20px;
}
.instructor-location svg {
  color: var(--red);
  flex-shrink: 0;
}
.instructor-info .btn {
  width: 100%;
  text-align: center;
  padding: 12px;
  font-size: 13px;
}

.instructor-card.hidden { display: none; }

/* ── FAQ Page ─────────────────────────────────────────────── */
.faq-section {
  background: var(--bg);
  padding: 100px 0;
}
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-item:first-child {
  border-top: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
