  align-items: center;
}

.navbar .container {
  display: flex;
  align-items: center;
  width: 100%;
}

.nav-logo {
  font-family: var(--font-head);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--white);
  text-transform: uppercase;
  flex-shrink: 0;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0;
  margin: 0 auto;
  padding: 0 24px;
}
.nav-links a {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0 16px;
  color: var(--gray);
  transition: color 0.2s;
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--white); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.nav-actions .btn {
  padding: 10px 20px;
  font-size: 12px;
