  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-page-title {
  font-size: clamp(42px, 6vw, 80px);
}

/* ── Sections ─────────────────────────────────────────────── */
.section {
  padding: 100px 0;
}
.section-sm {
  padding: 64px 0;
}
.section-dark {
  background: var(--bg);
}
.section-darker {
  background: #0d0d0d;
}
