  max-width: 640px;
  margin-top: 16px;
  line-height: 1.7;
}

.section-header.centered p {
  margin: 16px auto 0;
}

/* ── Community Promo ──────────────────────────────────────── */
.community-promo {
  background: var(--bg2);
  text-align: center;
  padding: 80px 0;
}
.community-promo h2 {
  font-size: clamp(40px, 6vw, 72px);
  color: var(--red);
  margin-bottom: 24px;
}
.community-promo p {
  font-size: 18px;
  color: var(--gray);
  max-width: 680px;
  margin: 0 auto 36px;
  line-height: 1.7;
}

/* ── Two Ways ─────────────────────────────────────────────── */
.two-ways {
  background: var(--bg);
}
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 60px;
}
.way-card {
  background: var(--bg2);
  padding: 64px 48px;
  position: relative;
