}
.way-card p {
  color: var(--gray);
  font-size: 16px;
  line-height: 1.7;
}

/* ── Studio Experience ────────────────────────────────────── */
.studio-exp {
  background: linear-gradient(135deg, #0f0f0f 0%, #1a0505 50%, #0f0f0f 100%);
  text-align: center;
  padding: 120px 0;
}
.studio-exp h2 {
  font-size: clamp(40px, 6vw, 72px);
  max-width: 800px;
