}
.free-trial .btn-outline {
  border-color: var(--white);
  color: var(--white);
  font-size: 18px;
  padding: 18px 48px;
}
.free-trial .btn-outline:hover {
  background: var(--white);
  color: var(--red);
}

/* ── Lifestyle Carousel ───────────────────────────────────── */
.carousel-section {
  background: var(--bg);
  padding: 80px 0;
}
.carousel-wrapper {
  position: relative;
  overflow: hidden;
  border-radius: 4px;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  height: 520px;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
}
.carousel-placeholder .icon {
  font-size: 48px;
