.country-dropdown a {
  display: block;
  padding: 10px 16px;
  font-size: 14px;
  color: var(--gray);
  transition: background 0.15s, color 0.15s;
}
.country-dropdown a:hover {
  background: var(--bg2);
  color: var(--white);
}

/* ── The Workout Page ─────────────────────────────────────── */
.method-section {
  background: var(--bg);
  padding: 100px 0;
}
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.method-text h2 {
  font-size: clamp(36px, 5vw, 60px);
  margin-bottom: 24px;
}
.method-text p {
  font-size: 17px;
  color: var(--gray);
  line-height: 1.8;
}

.schedule-section {
  background: var(--bg2);
  padding: 100px 0;
}
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 48px;
}
.schedule-table th {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gray);
  padding: 16px 24px;
  border-bottom: 2px solid var(--border);
  text-align: left;
}
.schedule-table td {
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  font-size: 16px;
}
.schedule-table tr:last-child td { border-bottom: none; }
.schedule-table td:first-child {
  font-family: var(--font-head);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.schedule-table td .muscle-badge {
  display: inline-block;
  background: rgba(255,0,0,0.12);
  color: var(--red);
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 2px;
  border: 1px solid rgba(255,0,0,0.25);
}
.schedule-table tr:hover td { background: rgba(255,255,255,0.02); }

/* Floor/Treadmill Toggle */
.toggle-section {
  background: var(--bg);
  padding: 100px 0;
}
.toggle-header {
  text-align: center;
  margin-bottom: 48px;
}
.toggle-header h2 {
  font-size: clamp(32px, 4vw, 54px);
  margin-bottom: 32px;
}
.toggle-controls {
  display: inline-flex;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.toggle-btn {
  font-family: var(--font-head);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 48px;
  color: var(--gray);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 48px;
}
.toggle-panel {
  display: none;
  background: var(--bg2);
  padding: 64px 48px;
}
.toggle-panel.active { display: block; }
.toggle-panel h3 {
  font-size: 36px;
  color: var(--red);
  margin-bottom: 20px;
}
.toggle-panel p {
  font-size: 17px;
  color: var(--gray);
  line-height: 1.8;
}
.toggle-panel-full {
  grid-column: 1 / -1;
}

/* ── Instructors Page ─────────────────────────────────────── */
.filter-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-bar label {
  font-family: var(--font-head);
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gray);
  margin-right: 8px;
}
.filter-btn {
  font-family: var(--font-head);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 10px 22px;
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--gray);
  border-radius: 2px;
  cursor: pointer;
  transition: all 0.2s;
}
.filter-btn:hover,
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
  transition: transform 0.2s, border-color 0.2s;
}
.instructor-card:hover {
  transform: translateY(-4px);
  border-color: var(--red);
}
.instructor-avatar {
  width: 100%;
  aspect-ratio: 1;
  background: var(--bg3);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-head);
  font-size: 48px;
  font-weight: 700;
  color: var(--red);
  position: relative;
  overflow: hidden;
}
.instructor-avatar::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,0,0,0.05) 0%, transparent 60%);
}
.instructor-info {
  padding: 24px;
}
.instructor-info h3 {
  font-size: 20px;
  margin-bottom: 8px;
}
.instructor-location {
  font-size: 13px;
  color: var(--gray2);
  letter-spacing: 0.08em;
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 20px;
}
.instructor-location svg {
  color: var(--red);
  flex-shrink: 0;
}
.instructor-info .btn {
  width: 100%;
  text-align: center;
  padding: 12px;
  font-size: 13px;
}

.instructor-card.hidden { display: none; }

/* ── FAQ Page ─────────────────────────────────────────────── */
.faq-section {
  background: var(--bg);
  padding: 100px 0;
}
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-item:first-child {
  border-top: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 0;
  text-align: left;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--white);
  font-family: var(--font-head);
  font-size: 20px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: color 0.2s;
}
.faq-question:hover { color: var(--red); }
.faq-question.open { color: var(--red); }

.faq-icon {
  width: 32px;
  height: 32px;
  border: 1px solid var(--border);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--gray);
  font-size: 18px;
  transition: all 0.3s;
}
.faq-question.open .faq-icon {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
  transform: rotate(45deg);
}

.faq-answer {
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.4s ease, padding 0.3s ease;
}
.faq-answer.open {
  max-height: 400px;
}
.faq-answer-inner {
  padding: 0 0 28px;
  color: var(--gray);
  font-size: 16px;
  line-height: 1.8;
  max-width: 680px;
}

/* ── Digital Platform Page ────────────────────────────────── */
.features-section {
  background: var(--bg);
  padding: 100px 0;
}
.features-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 60px;
}
.feature-card {
  background: var(--bg2);
  padding: 56px 48px;
  position: relative;
  overflow: hidden;
  transition: background 0.2s;
}
.feature-card:hover { background: #1f1f1f; }
.feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 0;
  background: var(--red);
  transition: height 0.3s;
}
.feature-card:hover::before { height: 100%; }

.feature-num {
  font-family: var(--font-head);
  font-size: 60px;
  font-weight: 700;
  color: var(--border);
  line-height: 1;
  margin-bottom: 24px;
}
.feature-card h3 {
  font-size: 26px;
  margin-bottom: 14px;
}
.feature-card p {
  font-size: 16px;
  color: var(--gray);
  line-height: 1.7;
}

.cta-join {
  background: linear-gradient(135deg, #0f0f0f 0%, #1a0505 50%, #0f0f0f 100%);
  padding: 120px 0;
  text-align: center;
}
.cta-join h2 {
  font-size: clamp(40px, 6vw, 72px);
  margin-bottom: 16px;
}
.cta-join p {
  font-size: 18px;
  color: var(--gray);
  max-width: 540px;
  margin: 0 auto 40px;
  line-height: 1.7;
}
.cta-join .btn-group {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
.cta-join .btn {
  font-size: 16px;
  padding: 16px 44px;
}

/* ── Mobile Menu ──────────────────────────────────────────── */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg);
  z-index: 150;
  padding: 80px 24px 40px;
  flex-direction: column;
  overflow-y: auto;
}
.mobile-nav.open { display: flex; }
.mobile-nav-close {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: var(--white);
  background: none;
  border: none;
  cursor: pointer;
}
.mobile-nav a {
  font-family: var(--font-head);
  font-size: 28px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gray);
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
  transition: color 0.2s;
}
.mobile-nav a:hover { color: var(--white); }
.mobile-nav .btn {
  margin-top: 32px;
  text-align: center;
}

/* ── Responsive ───────────────────────────────────────────── */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-toggle { display: flex; }
  .nav-actions { display: none; }
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .two-ways-grid,
  .method-grid,
  .toggle-content,
  .features-grid,
  .footer-grid { grid-template-columns: 1fr; }

  .way-card,
  .toggle-panel,
  .feature-card { padding: 40px 28px; }

  .instructor-grid { grid-template-columns: 1fr 1fr; }

  .section, .section-sm { padding: 64px 0; }

  .carousel-slide { height: 300px; }

  .hero { min-height: 70vh; }

  .newsletter-form { flex-direction: column; }
  .newsletter-form .btn { width: 100%; }

  .footer-bottom { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .hero-ctas { flex-direction: column; }
  .hero-ctas .btn { width: 100%; text-align: center; }
}

/* ── Divider / Red Line ───────────────────────────────────── */
.red-divider {
  width: 64px;
  height: 3px;
  background: var(--red);
  margin: 16px 0 32px;
}
.red-divider.centered { margin: 16px auto 32px; }

/* ── Utilities ────────────────────────────────────────────── */
.text-red { color: var(--red); }
.text-gray { color: var(--gray); }
.mt-8  { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mb-0  { margin-bottom: 0; }
